    public static function seed(): int
    {
        $count = 0;
        foreach (self::rows() as $row) {
            [$slug, $name, $category, $group, $equipment, $muscles, $kind, $atHome, $level, $cue, $steps] = $row;

            Exercise::updateOrCreate(['slug' => $slug], [
                'name' => $name,
                'category' => $category,
                'muscle_group' => $group,
                'equipment' => $equipment,
                'muscles' => $muscles,
                'kind' => $kind,
                'at_home' => $atHome,
                'level' => $level,
                'cue' => $cue,
                'instructions' => $steps,
            ]);
            $count++;
        }

        return $count;
    }
